/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 * }
 */
// 前序遍歷，空節點記為 "#"，以逗號分隔
// 時間複雜度: O(n)，空間複雜度: O(n)
function serialize(root: TreeNode | null): string {
    const out: string[] = [];
    const dfs = (node: TreeNode | null): void => {
        if (!node) {
            out.push('#');
            return;
        }
        out.push(String(node.val));
        dfs(node.left);
        dfs(node.right);
    };
    dfs(root);
    return out.join(',');
}

function deserialize(data: string): TreeNode | null {
    const tokens = data.split(',');
    let i = 0;
    const build = (): TreeNode | null => {
        const t = tokens[i++];
        if (t === '#') return null;
        const node = new TreeNode(Number(t));
        node.left = build();
        node.right = build();
        return node;
    };
    return build();
}

