/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */
// 前序遍歷，空節點記為 "#"，以逗號分隔
// 時間複雜度: O(n)，空間複雜度: O(n)
static int countNodes(struct TreeNode* node) {
    return node ? 1 + countNodes(node->left) + countNodes(node->right) : 0;
}

static void ser(struct TreeNode* node, char* buf, int* pos) {
    if (!node) {
        *pos += sprintf(buf + *pos, "#,");
        return;
    }
    *pos += sprintf(buf + *pos, "%d,", node->val);
    ser(node->left, buf, pos);
    ser(node->right, buf, pos);
}

/** Encodes a tree to a single string. */
char* serialize(struct TreeNode* root) {
    int n = countNodes(root);
    char* buf = malloc(n * 7 + (n + 1) * 2 + 1);   // 每個值最多 "-1000," 6 字元
    int pos = 0;
    ser(root, buf, &pos);
    buf[pos] = '\0';
    return buf;
}

static struct TreeNode* des(char** p) {
    if (**p == '#') {
        *p += 2;                                   // 跳過 "#,"
        return NULL;
    }
    struct TreeNode* node = malloc(sizeof(struct TreeNode));
    node->val = (int)strtol(*p, p, 10);            // strtol 會把 *p 移到數字之後
    (*p)++;                                        // 跳過 ','
    node->left = des(p);
    node->right = des(p);
    return node;
}

/** Decodes your encoded data to tree. */
struct TreeNode* deserialize(char* data) {
    char* p = data;
    return des(&p);
}

